//! Whole-text metadata and output admission do not mutate native sources.
use super::*;
#[test]
fn text_whole_no_slot_metadata_output_refusal_and_recovery_preserve_source_units(){
 let mut doc=crate::html::parse("<html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);let nodes=doc.nodes.len();page.begin_job();let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};b.state.node_limit=nodes;let Value::Host(owner)=b.create_generic_document().unwrap()else{panic!("owner")};let Value::Host(parent)=b.create_expanded_element(owner,&[Value::String(HTML_NAMESPACE.into()),Value::String("span".into())]).unwrap()else{panic!("parent")};let Value::Host(a)=b.inert_create_node(owner,"createTextNode",&[Value::StringUnits(vec![0xd83d])]).unwrap()else{panic!("text")};let Value::Host(cdata)=b.create_cdata_section(owner,&[Value::StringUnits(vec![0xde00])]).unwrap()else{panic!("CDATA")};let Value::Host(empty)=b.inert_create_node(owner,"createTextNode",&[Value::String(String::new())]).unwrap()else{panic!("empty")};b.mutate_inert_children(parent,"appendChild",&[Value::Host(a)]).unwrap();b.mutate_inert_children(parent,"appendChild",&[Value::Host(cdata)]).unwrap();assert!(node_index(a).is_none()&&node_index(cdata).is_none());assert!(matches!(b.native_whole_text(a).unwrap(),Value::String(s) if s=="😀"));
 let before=(b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.dom_commits,b.doc.nodes.len());let copies=b.state.copy_work;let metadata=2*(size_of::<u32>()+2*size_of::<&DomString>());for allowance in [0,metadata]{b.state.copy_work=allowance;assert!(b.native_whole_text(a).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.dom_commits,b.doc.nodes.len()),before);}b.state.copy_work=0;assert!(matches!(b.native_whole_text(empty).unwrap(),Value::String(s) if s.is_empty()));b.state.copy_work=copies;let limit=b.state.limits.host.string_bytes;b.state.limits.host.string_bytes=1;assert!(b.native_whole_text(cdata).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.dom_commits,b.doc.nodes.len()),before);b.state.limits.host.string_bytes=limit;assert!(matches!(b.native_whole_text(cdata).unwrap(),Value::String(s) if s=="😀"));assert_eq!(b.character_data_source(a).unwrap().code_units().collect::<Vec<_>>(),vec![0xd83d]);assert_eq!(b.character_data_source(cdata).unwrap().code_units().collect::<Vec<_>>(),vec![0xde00]);assert_eq!(b.inert_children(parent).unwrap(),[a,cdata]);assert_eq!(b.doc.nodes.len(),nodes);
}
